// Actor: QuaternionTransform (Math/Geometry Interface)
// Usage: apply(quat, vector) -> returns rotated vector
function q_mul(q1, q2) = [q1[0]*q2[0]-q1[1]*q2[1]-q1[2]*q2[2]-q1[3]*q2[3], q1[0]*q2[1]+q1[1]*q2[0]+q1[2]*q2[3]-q1[3]*q2[2], q1[0]*q2[2]-q1[1]*q2[3]+q1[2]*q2[0]+q1[3]*q2[1], q1[0]*q2[3]+q1[1]*q2[2]-q1[2]*q2[1]+q1[3]*q2[0]];
function q_rot(q, v) = let(r = q_mul(q_mul(q, [0, v[0], v[1], v[2]]), [-q[0], q[1], q[2], q[3]])) [r[1], r[2], r[3]];

// Actor: QuestAsset (Parametric Geometry Factory)
module quest_node(pos=[0,0,0], quat=[1,0,0,0], scale=1) {
    multmatrix([
        [scale, 0, 0, pos[0]], [0, scale, 0, pos[1]], [0, 0, scale, pos[2]], [0, 0, 0, 1]
    ]) rotate([0,0,0]) // Simplified local rotation mapping
    children();
}

// Composition Root
union() {
    quest_node(pos=[10, 0, 0], quat=[0.7, 0, 0.7, 0]) cube(5, center=true);
    quest_node(pos=[-10, 5, 0], quat=[1, 0, 0, 0]) sphere(3);
}

